`timescale 1ns / 1ps
// tb_irq_ctrl.sv - self-checking testbench for irq_ctrl (interface_spec.md).
//
// Structure
//   tb_irq_ctrl        : top; runs irq_ctrl_tb_core for N = 2, 5, 8 and 32 and
//                        prints the platform verdict line
//                          NIRMAAN-SIM <nonce> <n> passed, <m> failed
//                        followed by TEST PASSED / TEST FAILED ($fatal on failure).
//   irq_ctrl_tb_core   : one DUT, directed tests with explicit expected values,
//                        plus a reference model (written from the spec) that is
//                        compared against rdata, irq and irq_id at every rising
//                        edge, and a seeded random phase.
//
// Timing discipline (race avoidance)
//   - All stimulus changes at the falling edge of clk (or 1-4 ns after it).
//   - Directed checks sample 1 ns after the falling edge.
//   - The model checker samples in the active region of the rising edge, before
//     any nonblocking update, using the model state of the same instant.
//
// Spec clause coverage (interface_spec.md)
//   IRQ-RESET            tests 1, 12      IRQ-REG-RW / IRQ-PARAM  test 2
//   IRQ-READ             test 11 (+ all)  IRQ-LEVEL               tests 4, 5, 7
//   IRQ-EDGE             tests 6, 7       IRQ-DETECT-DISABLED     test 4
//   IRQ-W1C              tests 3, 8       IRQ-ACK                 tests 3, 9
//   IRQ-SET-WINS         tests 5, 6, 7    IRQ-MASK                tests 4, 6, 7, 10
//   IRQ-PRIORITY         tests 4, 10      IRQ-CLAIM               tests 4, 10, 11
//   IRQ-LATENCY          test 4           everything              test 13 (random + model)

module irq_ctrl_tb_core #(
    parameter integer N    = 8,
    parameter integer SEED = 1
) (
    output logic   done,
    output integer errors,
    output integer checks
);
    localparam [31:0]  MASK  = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);
    localparam integer H     = N - 1;
    localparam [4:0]   H5    = H[4:0];
    localparam integer NRAND = 4000;

    // ------------------------------------------------------------------
    // DUT
    // ------------------------------------------------------------------
    logic         clk = 1'b0;
    logic         rst_n;
    logic [N-1:0] src;
    logic         we;
    logic [1:0]   addr;
    logic [31:0]  wdata;
    wire  [31:0]  rdata;
    wire          irq;
    wire  [4:0]   irq_id;

    irq_ctrl #(.N(N)) dut (
        .clk    (clk),
        .rst_n  (rst_n),
        .src    (src),
        .we     (we),
        .addr   (addr),
        .wdata  (wdata),
        .rdata  (rdata),
        .irq    (irq),
        .irq_id (irq_id)
    );

    always #5 clk = ~clk;

    integer d_errors = 0;
    integer d_checks = 0;
    integer m_errors = 0;
    integer m_checks = 0;
    integer tnum     = 0;
    logic   chk_en   = 1'b0;

    // ------------------------------------------------------------------
    // Spec helper functions
    // ------------------------------------------------------------------
    // IRQ-PRIORITY: lowest-numbered active source, 0 when none.
    function automatic logic [4:0] f_lowest(input logic [31:0] act);
        integer k;
        logic   found;
        begin
            f_lowest = 5'd0;
            found    = 1'b0;
            for (k = 0; k < 32; k = k + 1)
                if (!found && act[k]) begin
                    f_lowest = k[4:0];
                    found    = 1'b1;
                end
        end
    endfunction

    // Register map / IRQ-CLAIM.
    function automatic logic [31:0] f_rdata(input logic [1:0] a, input logic [31:0] en,
                                            input logic [31:0] md, input logic [31:0] pd);
        logic [31:0] act;
        begin
            act = pd & en;
            case (a)
                2'd0:    f_rdata = en;
                2'd1:    f_rdata = md;
                2'd2:    f_rdata = pd;
                default: f_rdata = {(act != 32'd0), 26'd0, f_lowest(act)};
            endcase
        end
    endfunction

    // ------------------------------------------------------------------
    // Reference model (from interface_spec.md section 4)
    // ------------------------------------------------------------------
    logic [31:0] m_en, m_mode, m_pend, m_srcq;
    logic [31:0] m_det, m_clr, m_src32;
    integer      mb;

    always @(posedge clk) begin
        m_src32        = 32'd0;
        m_src32[N-1:0] = src;
        if (!rst_n) begin
            m_en   <= 32'd0;
            m_mode <= 32'd0;
            m_pend <= 32'd0;
            m_srcq <= 32'd0;
        end else begin
            // Detection: level sources whenever high; edge sources on low->high.
            m_det = 32'd0;
            for (mb = 0; mb < N; mb = mb + 1)
                if (m_src32[mb] && (!m_mode[mb] || !m_srcq[mb]))
                    m_det[mb] = 1'b1;
            // Clearing: W1C on PENDING, single-source acknowledge on CLAIM.
            m_clr = 32'd0;
            if (we && addr == 2'd2)
                m_clr = wdata & MASK;
            if (we && addr == 2'd3 && ({27'd0, wdata[4:0]} < N))
                m_clr[wdata[4:0]] = 1'b1;
            // A detection wins over a clear at the same edge.
            m_pend <= (m_det | (m_pend & ~m_clr)) & MASK;
            if (we && addr == 2'd0) m_en   <= wdata & MASK;
            if (we && addr == 2'd1) m_mode <= wdata & MASK;
            m_srcq <= m_src32;
        end
    end

    // Continuous model checker: sampled before the edge's updates.
    logic [31:0] c_act, c_rd;
    logic        c_irq;
    logic [4:0]  c_id;

    always @(posedge clk) begin
        if (chk_en) begin
            c_act    = m_pend & m_en;
            c_rd     = f_rdata(addr, m_en, m_mode, m_pend);
            c_irq    = (c_act != 32'd0);
            c_id     = f_lowest(c_act);
            m_checks = m_checks + 1;
            if (rdata !== c_rd || irq !== c_irq || irq_id !== c_id) begin
                if (m_errors < 20)
                    $display("ERROR [N=%0d] model mismatch at %0t (test %0d): addr %0d rdata 0x%08h exp 0x%08h, irq %b exp %b, irq_id %0d exp %0d",
                             N, $time, tnum, addr, rdata, c_rd, irq, c_irq, irq_id, c_id);
                m_errors = m_errors + 1;
            end
        end
    end

    // ------------------------------------------------------------------
    // Directed-test tasks (each starts and ends at a falling edge unless noted)
    // ------------------------------------------------------------------
    task automatic cmp_rd(input logic [1:0] a, input logic [31:0] exp);
        begin
            d_checks = d_checks + 1;
            if (rdata !== exp) begin
                if (d_errors < 20)
                    $display("ERROR [N=%0d] test %0d at %0t: read addr %0d got 0x%08h expected 0x%08h",
                             N, tnum, $time, a, rdata, exp);
                d_errors = d_errors + 1;
            end
        end
    endtask

    // Read register a and check it; consumes one clock cycle.
    task automatic chk_rd(input logic [1:0] a, input logic [31:0] exp);
        begin
            we   = 1'b0;
            addr = a;
            #1;
            cmp_rd(a, exp);
            @(negedge clk);
        end
    endtask

    // Check irq and irq_id; consumes one clock cycle.
    task automatic chk_irq(input logic exp_irq, input logic [4:0] exp_id);
        begin
            #1;
            d_checks = d_checks + 1;
            if (irq !== exp_irq || irq_id !== exp_id) begin
                if (d_errors < 20)
                    $display("ERROR [N=%0d] test %0d at %0t: irq %b irq_id %0d, expected irq %b irq_id %0d",
                             N, tnum, $time, irq, irq_id, exp_irq, exp_id);
                d_errors = d_errors + 1;
            end
            @(negedge clk);
        end
    endtask

    // One register write; takes effect at the next rising edge.
    task automatic wr(input logic [1:0] a, input logic [31:0] d);
        begin
            we    = 1'b1;
            addr  = a;
            wdata = d;
            @(negedge clk);
            we    = 1'b0;
            wdata = 32'd0;
        end
    endtask

    task automatic step(input integer n);
        integer j;
        begin
            for (j = 0; j < n; j = j + 1)
                @(negedge clk);
        end
    endtask

    task automatic set_src(input logic [31:0] v);
        begin
            src = v[N-1:0];
        end
    endtask

    // IRQ-READ: all four registers read within one half cycle, no clock edge.
    task automatic sweep_reads(input logic [31:0] e0, input logic [31:0] e1,
                               input logic [31:0] e2, input logic [31:0] e3);
        begin
            we   = 1'b0;
            addr = 2'd0; #1; cmp_rd(2'd0, e0);
            addr = 2'd3; #1; cmp_rd(2'd3, e3);
            addr = 2'd1; #1; cmp_rd(2'd1, e1);
            addr = 2'd2; #1; cmp_rd(2'd2, e2);
            @(negedge clk);
        end
    endtask

    // Return to ENABLE = MODE = PENDING = 0 with all sources low.
    task automatic cleanup;
        begin
            src = '0;
            wr(2'd0, 32'd0);
            wr(2'd1, 32'd0);
            wr(2'd2, 32'hFFFF_FFFF);
            chk_rd(2'd2, 32'd0);
        end
    endtask

    // ------------------------------------------------------------------
    // Stimulus
    // ------------------------------------------------------------------
    initial begin : stim
        integer      k;
        integer      seed;
        integer      cov_hi;
        integer      cov_lo;
        logic [31:0] exp_pd;
        logic [31:0] r1, r2, r3;

        done   = 1'b0;
        errors = 0;
        checks = 0;
        cov_hi = 0;
        cov_lo = 0;
        seed   = SEED;
        rst_n  = 1'b0;
        src    = '0;
        we     = 1'b0;
        addr   = 2'd0;
        wdata  = 32'd0;

        // ---- Test 1: reset values (IRQ-RESET, IRQ-PRIORITY id 0 when low)
        tnum = 1;
        @(negedge clk);
        chk_en = 1'b1;
        chk_rd(2'd0, 32'd0);
        chk_rd(2'd1, 32'd0);
        chk_rd(2'd2, 32'd0);
        chk_rd(2'd3, 32'd0);
        chk_irq(1'b0, 5'd0);
        rst_n = 1'b1;
        step(1);

        // ---- Test 2: ENABLE / MODE read-write, bits N and up (IRQ-REG-RW, IRQ-PARAM)
        tnum = 2;
        cleanup();
        wr(2'd0, 32'hFFFF_FFFF);
        chk_rd(2'd0, MASK);
        chk_rd(2'd1, 32'd0);
        chk_rd(2'd2, 32'd0);
        chk_irq(1'b0, 5'd0);
        wr(2'd1, 32'hFFFF_FFFF);
        chk_rd(2'd1, MASK);
        chk_rd(2'd0, MASK);
        wr(2'd0, 32'hA5C3_5A3C);
        chk_rd(2'd0, 32'hA5C3_5A3C & MASK);
        chk_rd(2'd1, MASK);
        wr(2'd1, 32'h3C5A_C3A5);
        chk_rd(2'd1, 32'h3C5A_C3A5 & MASK);
        chk_rd(2'd0, 32'hA5C3_5A3C & MASK);
        chk_rd(2'd2, 32'd0);
        wr(2'd0, 32'd0);
        wr(2'd1, 32'd0);
        chk_rd(2'd0, 32'd0);
        chk_rd(2'd1, 32'd0);
        chk_rd(2'd3, 32'd0);

        // ---- Test 3: PENDING / CLAIM writes never set a bit (IRQ-W1C, IRQ-ACK)
        tnum = 3;
        cleanup();
        wr(2'd2, 32'hFFFF_FFFF);
        chk_rd(2'd2, 32'd0);
        wr(2'd3, 32'd0);
        chk_rd(2'd2, 32'd0);
        wr(2'd3, 32'h0000_001F);
        chk_rd(2'd2, 32'd0);
        chk_irq(1'b0, 5'd0);

        // ---- Test 4: level detection, disabled detection, mask, claim, latency
        tnum = 4;
        cleanup();
        set_src(32'h2);
        chk_irq(1'b0, 5'd0);            // before the edge: irq does not follow src
        set_src(32'd0);
        chk_rd(2'd2, 32'h2);            // disabled source 1 still pending
        chk_irq(1'b0, 5'd0);
        chk_rd(2'd3, 32'd0);
        wr(2'd0, 32'h2);
        chk_irq(1'b1, 5'd1);
        chk_rd(2'd3, 32'h8000_0001);
        set_src(32'h1); step(1); set_src(32'd0);
        chk_rd(2'd2, 32'h3);
        chk_irq(1'b1, 5'd1);            // source 0 pending but disabled
        wr(2'd0, 32'h3);
        chk_irq(1'b1, 5'd0);
        chk_rd(2'd3, 32'h8000_0000);
        wr(2'd2, 32'h3);
        chk_irq(1'b0, 5'd0);            // falls right after the clearing edge
        set_src(32'h1);
        chk_irq(1'b0, 5'd0);            // not before the detecting edge
        set_src(32'd0);
        chk_irq(1'b1, 5'd0);            // high right after the detecting edge
        wr(2'd3, 32'd0);
        chk_irq(1'b0, 5'd0);
        chk_rd(2'd2, 32'd0);

        // ---- Test 5: set wins for a level source (IRQ-SET-WINS, IRQ-LEVEL)
        tnum = 5;
        cleanup();
        set_src(32'h1); step(1);
        chk_rd(2'd2, 32'h1);
        wr(2'd2, 32'h1);                // W1C while still high
        chk_rd(2'd2, 32'h1);
        wr(2'd3, 32'd0);                // acknowledge while still high
        chk_rd(2'd2, 32'h1);
        set_src(32'd0);
        wr(2'd3, 32'd0);
        chk_rd(2'd2, 32'd0);

        // ---- Test 6: rising-edge detection (IRQ-EDGE, IRQ-SET-WINS, IRQ-MASK)
        tnum = 6;
        cleanup();
        wr(2'd1, 32'h2);
        set_src(32'h2); step(1);
        chk_rd(2'd2, 32'h2);
        wr(2'd2, 32'h2);                // held high: clear sticks
        chk_rd(2'd2, 32'd0);
        step(3);
        chk_rd(2'd2, 32'd0);            // held high sets only once
        set_src(32'd0); step(1);
        chk_rd(2'd2, 32'd0);
        set_src(32'h2); step(1);
        chk_rd(2'd2, 32'h2);            // a new rising edge
        set_src(32'd0); step(1);
        set_src(32'h2);
        wr(2'd2, 32'h2);                // rising edge and clear at the same edge
        chk_rd(2'd2, 32'h2);
        wr(2'd2, 32'h2);                // held high, no new edge
        chk_rd(2'd2, 32'd0);
        set_src(32'd0); step(1);
        wr(2'd0, 32'h2);
        chk_irq(1'b0, 5'd0);
        set_src(32'h2); step(1);
        chk_irq(1'b1, 5'd1);
        chk_rd(2'd3, 32'h8000_0001);
        set_src(32'd0);
        wr(2'd3, 32'h1);
        chk_irq(1'b0, 5'd0);
        chk_rd(2'd2, 32'd0);

        // ---- Test 7: level and edge sources together
        tnum = 7;
        cleanup();
        wr(2'd1, 32'h2);
        set_src(32'h3); step(3);
        chk_rd(2'd2, 32'h3);
        wr(2'd2, 32'h3);                // level bit 0 re-detected, edge bit 1 clears
        chk_rd(2'd2, 32'h1);
        wr(2'd0, 32'h3);
        chk_irq(1'b1, 5'd0);
        wr(2'd0, 32'h2);
        chk_irq(1'b0, 5'd0);
        chk_rd(2'd3, 32'd0);

        // ---- Test 8: write-one-to-clear (IRQ-W1C, IRQ-PARAM)
        tnum = 8;
        cleanup();
        set_src(MASK); step(1); set_src(32'd0);
        chk_rd(2'd2, MASK);
        wr(2'd2, 32'h5555_5555);
        exp_pd = MASK & 32'hAAAA_AAAA;
        chk_rd(2'd2, exp_pd);
        wr(2'd2, 32'd0);
        chk_rd(2'd2, exp_pd);
        wr(2'd2, ~MASK);
        chk_rd(2'd2, exp_pd);
        wr(2'd2, 32'hFFFF_FFFF);
        chk_rd(2'd2, 32'd0);

        // ---- Test 9: acknowledge through CLAIM (IRQ-ACK)
        tnum = 9;
        cleanup();
        set_src(MASK); step(1); set_src(32'd0);
        exp_pd = MASK;
        chk_rd(2'd2, exp_pd);
        wr(2'd3, 32'hFFFF_FFE1);        // number 1; upper bits ignored
        exp_pd = exp_pd & ~32'h2;
        chk_rd(2'd2, exp_pd);
        if (N < 32) begin
            wr(2'd3, N);                // out of range: no change
            chk_rd(2'd2, exp_pd);
            wr(2'd3, 32'h0000_001F);
            chk_rd(2'd2, exp_pd);
        end
        wr(2'd3, 32'd0);
        exp_pd = exp_pd & ~32'h1;
        chk_rd(2'd2, exp_pd);
        wr(2'd3, H);
        exp_pd = exp_pd & ~(32'd1 << H);
        chk_rd(2'd2, exp_pd);
        chk_rd(2'd0, 32'd0);
        chk_rd(2'd1, 32'd0);
        wr(2'd2, 32'hFFFF_FFFF);
        chk_rd(2'd2, 32'd0);

        // ---- Test 10: priority, claim and drain (IRQ-PRIORITY, IRQ-MASK, IRQ-CLAIM)
        tnum = 10;
        cleanup();
        set_src(32'd1 << H); step(1); set_src(32'd0);
        wr(2'd0, MASK & ~(32'd1 << H));
        chk_irq(1'b0, 5'd0);            // pending but not enabled: id 0
        chk_rd(2'd3, 32'd0);
        wr(2'd0, MASK);
        chk_irq(1'b1, H5);              // lower sources enabled but not pending
        chk_rd(2'd3, 32'h8000_0000 | H);
        set_src(MASK); step(1); set_src(32'd0);
        wr(2'd0, 32'd0);
        chk_irq(1'b0, 5'd0);
        chk_rd(2'd3, 32'd0);
        wr(2'd0, 32'd1 << H);
        chk_irq(1'b1, H5);
        wr(2'd0, MASK);
        for (k = 0; k < N; k = k + 1) begin
            chk_irq(1'b1, k[4:0]);
            chk_rd(2'd3, 32'h8000_0000 | k);
            wr(2'd3, k);
        end
        chk_irq(1'b0, 5'd0);
        chk_rd(2'd3, 32'd0);
        chk_rd(2'd2, 32'd0);

        // ---- Test 11: reads take no clock edge and change nothing (IRQ-READ)
        tnum = 11;
        cleanup();
        wr(2'd0, 32'hFFFF_FFFE);
        wr(2'd1, 32'h5555_5555);
        set_src((32'd1 << H) | 32'd1); step(1); set_src(32'd0);
        exp_pd = (32'd1 << H) | 32'd1;
        sweep_reads(MASK & 32'hFFFF_FFFE, MASK & 32'h5555_5555, exp_pd, 32'h8000_0000 | H);
        sweep_reads(MASK & 32'hFFFF_FFFE, MASK & 32'h5555_5555, exp_pd, 32'h8000_0000 | H);
        chk_rd(2'd2, exp_pd);
        chk_rd(2'd3, 32'h8000_0000 | H);
        chk_rd(2'd0, MASK & 32'hFFFF_FFFE);
        chk_rd(2'd1, MASK & 32'h5555_5555);

        // ---- Test 12: reset in the middle of operation (IRQ-RESET)
        tnum = 12;
        cleanup();
        wr(2'd0, MASK);
        wr(2'd1, 32'hAAAA_AAAA);
        set_src(MASK); step(2);
        chk_rd(2'd2, MASK);
        chk_irq(1'b1, 5'd0);
        rst_n = 1'b0;                   // sources stay high through reset
        step(1);
        chk_rd(2'd0, 32'd0);
        chk_rd(2'd1, 32'd0);
        chk_rd(2'd2, 32'd0);
        chk_rd(2'd3, 32'd0);
        chk_irq(1'b0, 5'd0);
        rst_n = 1'b1;
        step(1);
        chk_rd(2'd2, MASK);             // MODE reset to level: all detected again
        chk_rd(2'd0, 32'd0);
        chk_irq(1'b0, 5'd0);
        set_src(32'd0);
        wr(2'd2, 32'hFFFF_FFFF);
        chk_rd(2'd2, 32'd0);

        // ---- Test 13: seeded random traffic, checked by the reference model
        tnum = 13;
        cleanup();
        for (k = 0; k < NRAND; k = k + 1) begin
            r1 = $random(seed);
            r2 = $random(seed);
            r3 = $random(seed);
            if (k[6] == 1'b1)
                src = '0;               // quiet spells let pending drain
            else if (r2[2:0] == 3'd0)
                src = r1[N-1:0];
            rst_n = (r2[15:8] != 8'd0);
            we    = r2[4] & r2[5];
            addr  = r2[7:6];
            wdata = r2[16] ? {27'd0, r3[4:0]} : r3;
            @(negedge clk);
            if (irq === 1'b1) cov_hi = cov_hi + 1;
            if (irq === 1'b0) cov_lo = cov_lo + 1;
        end
        rst_n = 1'b1;
        we    = 1'b0;
        src   = '0;
        step(2);

        // ---- Wrap-up
        chk_en = 1'b0;
        errors = d_errors + m_errors;
        checks = d_checks + m_checks;
        if (d_checks == 0 || m_checks == 0) begin
            $display("ERROR [N=%0d] checkers did not run: directed %0d, model %0d", N, d_checks, m_checks);
            errors = errors + 1;
        end
        if (cov_hi == 0 || cov_lo == 0) begin
            $display("ERROR [N=%0d] random phase did not exercise irq both ways: high %0d, low %0d", N, cov_hi, cov_lo);
            errors = errors + 1;
        end
        $display("[N=%0d] directed checks %0d (errors %0d), model checks %0d (errors %0d), random irq high %0d / low %0d cycles",
                 N, d_checks, d_errors, m_checks, m_errors, cov_hi, cov_lo);
        done = 1'b1;
    end
endmodule

module tb_irq_ctrl;
    logic   done2, done5, done8, done32;
    integer err2, err5, err8, err32;
    integer chk2, chk5, chk8, chk32;
    integer total_err;
    integer total_chk;
    integer n_pass;
    integer n_fail;

    // Platform nonce for the verdict line, read from a plusarg.
    reg [8*128-1:0] nonce;
    reg             nonce_ok;
    reg             verdict_done;

    irq_ctrl_tb_core #(.N(2),  .SEED(22)) u_n2  (.done(done2),  .errors(err2),  .checks(chk2));
    irq_ctrl_tb_core #(.N(5),  .SEED(55)) u_n5  (.done(done5),  .errors(err5),  .checks(chk5));
    irq_ctrl_tb_core #(.N(8),  .SEED(88)) u_n8  (.done(done8),  .errors(err8),  .checks(chk8));
    irq_ctrl_tb_core #(.N(32), .SEED(32)) u_n32 (.done(done32), .errors(err32), .checks(chk32));

    initial begin
        verdict_done = 1'b0;
        nonce_ok     = 1'b0;
        nonce        = "unset";
        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce))      nonce_ok = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) nonce_ok = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce))         nonce_ok = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce))         nonce_ok = 1'b1;
        if (!nonce_ok)
            $display("WARNING: no nonce plusarg found (+NIRMAAN_NONCE=...); verdict nonce printed as 'unset'");
    end

    // The platform verdict line; printed exactly once.
    task automatic print_verdict(input integer passed, input integer failed);
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            end
        end
    endtask

    initial begin
        wait (done2 === 1'b1 && done5 === 1'b1 && done8 === 1'b1 && done32 === 1'b1);
        #1;
        total_err = err2 + err5 + err8 + err32;
        total_chk = chk2 + chk5 + chk8 + chk32;
        n_fail    = total_err;
        n_pass    = (total_chk > total_err) ? (total_chk - total_err) : 0;
        if (total_chk == 0 && n_fail == 0)
            n_fail = 1;                 // no checks at all counts as a failure
        $display("irq_ctrl testbench: %0d checks, %0d errors (N=2: %0d, N=5: %0d, N=8: %0d, N=32: %0d)",
                 total_chk, total_err, err2, err5, err8, err32);
        print_verdict(n_pass, n_fail);
        if (n_fail == 0 && total_chk > 0) begin
            $display("TEST PASSED");
            $finish;
        end else begin
            $display("TEST FAILED");
            $fatal(1, "irq_ctrl testbench failed with %0d errors", n_fail);
        end
    end

    initial begin
        #1000000;
        print_verdict(0, 1);
        $display("TEST FAILED");
        $fatal(1, "irq_ctrl testbench timed out");
    end
endmodule
