// Directed self-checking testbench for irq_ctrl (N = 8).
// Stimulus changes 1 ns after each rising clock edge; checks are made
// combinationally (rdata, irq, irq_id) before the next edge.
`timescale 1ns / 1ps
module tb_irq_ctrl;
    localparam integer N = 8;

    reg          clk   = 1'b0;
    reg          rst_n = 1'b0;
    reg  [N-1:0] src   = {N{1'b0}};
    reg          we    = 1'b0;
    reg  [1:0]   addr  = 2'd0;
    reg  [31:0]  wdata = 32'd0;
    wire [31:0]  rdata;
    wire         irq;
    wire [4:0]   irq_id;

    irq_ctrl #(.N(N)) dut (
        .clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr),
        .wdata(wdata), .rdata(rdata), .irq(irq), .irq_id(irq_id)
    );

    always #50 clk = ~clk;

    integer n_pass = 0;
    integer n_fail = 0;
    reg     verdict_done = 1'b0;
    reg     have_nonce   = 1'b0;
    reg [8*128-1:0] nonce_r;

    // ---------------------------------------------------------------- helpers
    task tick;
        begin
            @(posedge clk);
            #1;
        end
    endtask

    task wr(input [1:0] a, input [31:0] d);
        begin
            addr  = a;
            wdata = d;
            we    = 1'b1;
            tick;
            we    = 1'b0;
            wdata = 32'd0;
        end
    endtask

    task chk(input [8*48-1:0] what, input [31:0] got, input [31:0] exp);
        begin
            if (got === exp)
                n_pass = n_pass + 1;
            else begin
                n_fail = n_fail + 1;
                $display("FAIL %0s: got %h expected %h at %0t", what, got, exp, $time);
            end
        end
    endtask

    task rd(input [1:0] a, input [31:0] exp, input [8*48-1:0] what);
        begin
            addr = a;
            #1;
            chk(what, rdata, exp);
        end
    endtask

    task chk_irq(input exp_irq, input [4:0] exp_id, input [8*48-1:0] what);
        begin
            #1;
            chk(what, {31'd0, irq}, {31'd0, exp_irq});
            chk(what, {27'd0, irq_id}, {27'd0, exp_id});
            rd(2'd3, {exp_irq, 26'd0, exp_id}, what);
        end
    endtask

    task print_verdict;
        integer k;
        reg [7:0] c;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $write("NIRMAAN-SIM ");
                if (have_nonce) begin
                    for (k = 127; k >= 0; k = k - 1) begin
                        c = nonce_r[k*8 +: 8];
                        if (c != 8'd0)
                            $write("%c", c);
                    end
                end else
                    $write("none");
                $display(" %0d passed, %0d failed", n_pass, n_fail);
            end
        end
    endtask

    // --------------------------------------------------------------- watchdog
    initial begin
        #2000000;
        $display("FAIL watchdog: simulation timed out");
        n_fail = n_fail + 1;
        print_verdict;
        $finish;
    end

    // ------------------------------------------------------------------ tests
    initial begin
        nonce_r = {8*128{1'b0}};
        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce_r))          have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce_r))     have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce_r)) have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce_r))             have_nonce = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce_r))             have_nonce = 1'b1;

        // T1 reset [IRQ-RESET]
        rst_n = 1'b0; src = 8'h00;
        tick; tick;
        rd(2'd0, 32'h0, "reset ENABLE");
        rd(2'd1, 32'h0, "reset MODE");
        rd(2'd2, 32'h0, "reset PENDING");
        chk_irq(1'b0, 5'd0, "reset irq/claim");
        rst_n = 1'b1;
        tick;

        // T2 register read/write, upper bits [IRQ-REG-RW] [IRQ-PARAM] [IRQ-READ]
        wr(2'd0, 32'hFFFF_FFFF);
        rd(2'd0, 32'h0000_00FF, "ENABLE write all ones");
        wr(2'd1, 32'hA5A5_A5A5);
        rd(2'd1, 32'h0000_00A5, "MODE write");
        rd(2'd0, 32'h0000_00FF, "ENABLE kept over MODE write");
        wr(2'd0, 32'h0000_003C);
        rd(2'd0, 32'h0000_003C, "ENABLE rewrite");
        rd(2'd2, 32'h0, "PENDING still zero");
        rd(2'd3, 32'h0, "CLAIM zero");
        tick;
        rd(2'd0, 32'h0000_003C, "read did not change ENABLE");
        rd(2'd1, 32'h0000_00A5, "read did not change MODE");
        rd(2'd2, 32'h0, "read did not change PENDING");
        wr(2'd1, 32'h0);
        wr(2'd0, 32'h0);
        rd(2'd0, 32'h0, "ENABLE cleared");
        rd(2'd1, 32'h0, "MODE cleared");
        wr(2'd2, 32'hFFFF_FFFF);
        rd(2'd2, 32'h0, "PENDING write never sets");

        // T3 level detection while disabled [IRQ-LEVEL] [IRQ-DETECT-DISABLED] [IRQ-MASK]
        src = 8'h04;
        tick;
        src = 8'h00;
        rd(2'd2, 32'h0000_0004, "level detect src2 disabled");
        chk_irq(1'b0, 5'd0, "disabled source no irq");
        tick;
        rd(2'd2, 32'h0000_0004, "pending held after src low");
        wr(2'd0, 32'h0000_0004);
        chk_irq(1'b1, 5'd2, "enable src2 raises irq");

        // T4 write-1-to-clear and acknowledge [IRQ-W1C] [IRQ-ACK] [IRQ-PRIORITY]
        src = 8'h21;
        tick;
        src = 8'h00;
        rd(2'd2, 32'h0000_0025, "level detect src0 src5");
        chk_irq(1'b1, 5'd2, "only src2 enabled");
        wr(2'd0, 32'h0000_0025);
        chk_irq(1'b1, 5'd0, "src0 highest priority");
        wr(2'd2, 32'h0000_0001);
        rd(2'd2, 32'h0000_0024, "W1C clears bit0 only");
        chk_irq(1'b1, 5'd2, "after W1C src2");
        wr(2'd2, 32'h0000_0000);
        rd(2'd2, 32'h0000_0024, "W1C zeros leave bits");
        wr(2'd3, 32'd2);
        rd(2'd2, 32'h0000_0020, "ack src2 clears only it");
        chk_irq(1'b1, 5'd5, "after ack src5");
        wr(2'd3, 32'd8);
        rd(2'd2, 32'h0000_0020, "ack N changes nothing");
        wr(2'd3, 32'd31);
        rd(2'd2, 32'h0000_0020, "ack 31 changes nothing");
        wr(2'd3, 32'hFFFF_FFE5);
        rd(2'd2, 32'h0, "ack uses wdata[4:0]");
        chk_irq(1'b0, 5'd0, "all cleared irq low");

        // T5 set wins over clear, level source [IRQ-SET-WINS] [IRQ-LATENCY]
        wr(2'd0, 32'h0000_0008);
        src = 8'h08;
        tick;
        rd(2'd2, 32'h0000_0008, "level src3 detected");
        chk_irq(1'b1, 5'd3, "irq at detect edge");
        wr(2'd3, 32'd3);
        rd(2'd2, 32'h0000_0008, "ack while high stays");
        chk_irq(1'b1, 5'd3, "irq stays after ack");
        wr(2'd2, 32'h0000_0008);
        rd(2'd2, 32'h0000_0008, "W1C while high stays");
        src = 8'h00;
        wr(2'd2, 32'h0000_0008);
        rd(2'd2, 32'h0, "W1C after src low");
        chk_irq(1'b0, 5'd0, "irq low after clear");

        // T6 rising-edge mode [IRQ-EDGE] [IRQ-SET-WINS] [IRQ-MASK]
        wr(2'd0, 32'h0);
        wr(2'd1, 32'h0000_0010);
        wr(2'd0, 32'h0000_0010);
        rd(2'd1, 32'h0000_0010, "MODE src4 edge");
        src = 8'h10;
        tick;
        rd(2'd2, 32'h0000_0010, "edge detect src4");
        chk_irq(1'b1, 5'd4, "edge src4 irq");
        wr(2'd2, 32'h0000_0010);
        rd(2'd2, 32'h0, "edge held high clears");
        tick; tick;
        rd(2'd2, 32'h0, "edge held high sets once");
        chk_irq(1'b0, 5'd0, "edge held high no irq");
        src = 8'h00;
        tick;
        rd(2'd2, 32'h0, "falling edge no detect");
        src = 8'h10;
        tick;
        rd(2'd2, 32'h0000_0010, "second rising edge");
        wr(2'd3, 32'd4);
        rd(2'd2, 32'h0, "ack edge src while high");
        src = 8'h00;
        tick;
        src = 8'h10;
        wr(2'd3, 32'd4);
        rd(2'd2, 32'h0000_0010, "edge detect wins over ack");
        chk_irq(1'b1, 5'd4, "edge set-wins irq");
        wr(2'd2, 32'h0000_0010);
        rd(2'd2, 32'h0, "edge src cleared");
        src = 8'h00;
        tick;

        // T7 priority and mask [IRQ-PRIORITY] [IRQ-MASK] [IRQ-CLAIM]
        wr(2'd1, 32'h0);
        wr(2'd0, 32'h0000_00FF);
        src = 8'hF0;
        tick;
        src = 8'h00;
        rd(2'd2, 32'h0000_00F0, "level detect src4-7");
        chk_irq(1'b1, 5'd4, "priority lowest src4");
        wr(2'd0, 32'h0000_00E0);
        chk_irq(1'b1, 5'd5, "priority src5");
        wr(2'd0, 32'h0000_0080);
        chk_irq(1'b1, 5'd7, "priority src7");
        wr(2'd0, 32'h0000_000F);
        chk_irq(1'b0, 5'd0, "masked pending no irq");
        wr(2'd2, 32'h0000_00FF);
        rd(2'd2, 32'h0, "all pending cleared");
        src = 8'h01;
        tick;
        src = 8'h00;
        rd(2'd2, 32'h0000_0001, "level detect src0");
        wr(2'd0, 32'h0000_0001);
        chk_irq(1'b1, 5'd0, "src0 claim 0x80000000");
        wr(2'd3, 32'd0);
        rd(2'd2, 32'h0, "ack src0");
        chk_irq(1'b0, 5'd0, "after ack src0");

        // T8 synchronous reset of non-zero state [IRQ-RESET]
        wr(2'd0, 32'h0000_005A);
        wr(2'd1, 32'h0000_0033);
        src = 8'h80;
        tick;
        src = 8'h00;
        rd(2'd2, 32'h0000_0080, "pending src7 before reset");
        rst_n = 1'b0;
        #1;
        rd(2'd0, 32'h0000_005A, "reset waits for clock edge");
        tick;
        rd(2'd0, 32'h0, "reset clears ENABLE");
        rd(2'd1, 32'h0, "reset clears MODE");
        rd(2'd2, 32'h0, "reset clears PENDING");
        chk_irq(1'b0, 5'd0, "reset clears irq");
        rst_n = 1'b1;
        tick;

        print_verdict;
        $finish;
    end
endmodule
